mapper.select:
SELECT t.ID AS id, t.INSTANCE_ID AS instanceId, t.NODE_ID AS nodeId, t.TASK_STATUS AS taskStatus, t.PAYLOAD AS payload, t.ACTION_DATA AS actionData, t.ENV_CODE AS envCode, t.DELETED AS deleted, t.CREATE_USER AS createUser, t.CREATE_TIME AS createTime, t.UPDATE_USER AS updateUser, t.UPDATE_TIME AS updateTime FROM AST_FLOW_HUMAN_TASK t WHERE (t.DELETED = 0 OR t.DELETED IS NULL)
AND t.INSTANCE_ID = #{req.instanceId}
AND t.NODE_ID LIKE CONCAT('%', #{req.nodeId}, '%')
AND t.TASK_STATUS = #{req.taskStatus}
AND t.ENV_CODE = #{req.envCode}
ORDER BY t.UPDATE_TIME DESC, t.ID DESC
